            $a('seo-einfach','SEO','SEO einfach erklärt','Suchmaschinen und geteilten Links verständliche Seitentitel, Beschreibungen und Vorschaubilder geben.',['Öffnen Sie SEO.','Prüfen Sie Titelvorlage und Standardbeschreibung.','Tragen Sie die spätere Hauptadresse als Canonical-Basis ein.','Wählen Sie ein geeignetes OG-Bild.'],'SEO verbessert nicht automatisch ein Ranking. Die Felder helfen Suchmaschinen, die Website korrekt zu verstehen.',Seo::getUrl(),'SEO bearbeiten',['suchmaschine','google','teilen']),
            $a('index-noindex','SEO','Was bedeutet index / noindex?','Festlegen, ob Suchmaschinen die Website in Suchergebnissen aufnehmen dürfen.',['Lassen Sie während Vorbereitung und Prüfung „noindex“ aktiv.','Wählen Sie „index, follow“ erst vor einer ausdrücklich freigegebenen öffentlichen Veröffentlichung.','Prüfen Sie danach die Einstellung erneut.'],'„follow“ erlaubt das Verfolgen von Links. „nofollow“ bittet Suchmaschinen, Links nicht weiterzuverfolgen.',Seo::getUrl(),'SEO bearbeiten',['robots','nofollow','indexierung']),
            $a('meta-beschreibung','SEO','Meta-Beschreibung','Eine kurze Zusammenfassung für Suchergebnisse festlegen.',['Formulieren Sie ein bis zwei klare Sätze über Sebastian und sein Angebot.','Vermeiden Sie Listen von Suchbegriffen.','Speichern Sie die Beschreibung und prüfen Sie die Veröffentlichung.'],'Suchmaschinen können trotzdem einen anderen Textausschnitt auswählen.',Seo::getUrl(),'SEO bearbeiten',['description','snippet','suchergebnis']),
            $a('canonical','SEO','Canonical URL','Suchmaschinen die bevorzugte Hauptadresse der Website mitteilen.',['Tragen Sie später die vollständige öffentliche Hauptadresse ein.','Verwenden Sie HTTPS und keine lokale Adresse.','Ändern Sie die Adresse nur bei einem bewussten Domain-Wechsel.'],'Die Canonical-Basis ist noch keine Domain- oder DNS-Änderung.',Seo::getUrl(),'SEO bearbeiten',['hauptadresse','domain','url']),
            $a('og-bild','SEO','Open-Graph-Bild','Das Standard-Vorschaubild beim Teilen in sozialen Netzwerken und Messengern festlegen.',['Laden Sie zuerst ein geeignetes Bild in Medien hoch.','Wählen Sie es unter „Standard-OG-Bild“.','Prüfen Sie Bildausschnitt und Rechte.','Veröffentlichen Sie die Änderung.'],'Plattformen speichern Vorschaubilder teilweise im Cache und zeigen Änderungen eventuell verzögert.',Seo::getUrl(),'SEO bearbeiten',['og','social preview','messenger']),
            $a('consent-einfach','Cookie / Consent','Cookie / Consent einfach erklärt','Besucher selbst entscheiden lassen, bevor optionale externe Dienste geladen werden.',['Öffnen Sie Cookie / Consent.','Aktivieren Sie nur Kategorien, die wirklich benötigt werden.','Formulieren Sie einen kurzen Banner-Text und prüfen Sie den Datenschutz-Link.','Erhöhen Sie die Version, wenn Besucher erneut entscheiden müssen.'],'Notwendige Funktionen bleiben immer aktiv. Eine Einwilligung ersetzt keine rechtliche Prüfung.',Consent::getUrl(),'Cookie / Consent bearbeiten',['cookie','einwilligung','datenschutz']),
            $a('externe-medien','Cookie / Consent','Externe Medien und Einwilligung','YouTube- oder Vimeo-Inhalte erst nach einer bewussten Entscheidung laden.',['Lassen Sie „Externe Medien benötigen Einwilligung“ aktiv.','Besucher können zunächst nur die Website ohne externen Film nutzen.','Nach Zustimmung wird ausschließlich der angeforderte Film geladen.','Die Entscheidung kann über „Cookie Settings“ geändert werden.'],'Lokale Bilder, Videos und Musik benötigen diese externe Verbindung nicht.',Consent::getUrl(),'Cookie / Consent bearbeiten',['youtube','vimeo','iframe']),
            $a('analytics-einrichten','Analytics','Analytics einrichten','Einen externen Statistik-Anbieter vorbereiten, ohne Zugangsdaten oder Scripts frei einzugeben.',['Wählen Sie Google Analytics 4 oder Plausible.','Tragen Sie nur die öffentliche Measurement-ID beziehungsweise Website-Domain ein.','Aktivieren Sie in Cookie / Consent die Kategorie Analyse.','Speichern, prüfen und veröffentlichen Sie die Konfiguration.'],'Ohne gültige Konfiguration und Zustimmung wird kein Tracking geladen.',Analytics::getUrl(),'Analytics bearbeiten',['ga4','plausible','measurement id']),
            $a('analytics-export','Analytics','Analytics-Bericht exportieren','Einen Bericht direkt beim gewählten Anbieter herunterladen.',['Öffnen Sie das Dashboard des Analytics-Anbieters.','Wählen Sie Zeitraum und gewünschte Auswertung.','Nutzen Sie die Export-Funktion des Anbieters, zum Beispiel CSV oder PDF.','Speichern Sie die Datei an einem sicheren Ort.'],'Die CMS speichert keine eigenen Besucherprofile und baut kein separates Statistiksystem.',Analytics::getUrl(),'Analytics öffnen',['csv','pdf','bericht','download']),
            $a('analytics-ai','Analytics','Analytics mit einem KI-Assistenten auswerten','Einen exportierten Bericht mit einem frei gewählten KI-Assistenten verständlich analysieren.',['Exportieren Sie einen Bericht ohne unnötige personenbezogene Daten.','Laden Sie die Datei bei einem von Ihnen gewählten KI-Dienst hoch.','Beschreiben Sie Ziel, Zeitraum und wichtige Fragen.','Prüfen Sie Empfehlungen immer selbst, bevor Sie Inhalte ändern.'],'Keine Passwörter, Tokens oder privaten Besucherdaten hochladen.',Analytics::getUrl(),'Analytics öffnen',['chatgpt','claude','gemini','ki'],"Analysiere diesen Website-Bericht. Welche Seiten werden häufig besucht? Wo verlassen Nutzer die Website? Welche Quellen bringen Besucher? Welche konkreten Verbesserungen empfiehlst du?"),
        ];
    }

    public function search(string $query='',string $category='Alle'): array
    {
        $needle=mb_strtolower(trim($query));
        return array_values(array_filter($this->articles(),function($article) use($needle,$category){
            if($category!=='Alle' && $article['category']!==$category)return false;
            if($needle==='')return true;
            $text=implode(' ',[$article['title'],$article['purpose'],$article['tips'],implode(' ',$article['steps']),implode(' ',$article['keywords']),$article['example']??'']);
            return str_contains(mb_strtolower($text),$needle);
        }));
    }
}
